      row.append(summary);
      const open = element('button', '', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => navigate(`/projects/${project.id}`));
      row.append(open);
      const archive = element('button', 'archive-button', project.archived ? 'Restore project' : 'Archive project');
      archive.type = 'button';
      archive.addEventListener('click', async () => {
        try {
          await request(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
          project.archived = !project.archived;
          drawProjects();
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      row.append(archive);
      list.append(row);
    }
  }
  filter.addEventListener('change', drawProjects);
  drawProjects();
  content.append(searchForm, filterField, title, list);

  searchForm.addEventListener('submit', event => {
    event.preventDefault();
    appliedSearch = searchInput.value.trim();
    drawProjects();
  });

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    try {
      await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      navigate('/');
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });
}

